package com.beeboee.magnot.server;import com.beeboee.magnot.network.MagnotNetwork;import com.beeboee.magnot.registry.MagnotItems;import net.minecraft.entity.player.ServerPlayerEntity;import net.minecraftforge.event.entity.player.*;import net.minecraftforge.eventbus.api.SubscribeEvent;public final class MagnotForgeEvents{private MagnotForgeEvents(){}@SubscribeEvent public static void login(PlayerEvent.PlayerLoggedInEvent e){if(e.getPlayer() instanceof ServerPlayerEntity)MagnotNetwork.sync((ServerPlayerEntity)e.getPlayer());}@SubscribeEvent public static void dimension(PlayerEvent.PlayerChangedDimensionEvent e){if(e.getPlayer() instanceof ServerPlayerEntity)MagnotNetwork.sync((ServerPlayerEntity)e.getPlayer());}@SubscribeEvent public static void left(PlayerInteractEvent.LeftClickBlock e){if(e.getPlayer().getMainHandItem().getItem()==MagnotItems.FERROUS_TUBE.get())e.setCanceled(true);}}
